func TestGenVLAN(t *testing.T) {
	fake := opnsensetest.New(t)
	h := newHarness(t, fake, NewVLANResource())
	plan := genVLANPlan()
	var got genVLANModel
	st, ok := h.create(plan, &got)
	if !ok {
		t.Fatal("create failed")
	}
	id := got.ID.ValueString()
	rec, ok := fake.Get("vlan", id)
	if !ok {
		t.Fatal("not stored")
	}
	if !sameValues(rec["if"], "igb1") {
		t.Errorf("if: stored %q, want %q", rec["if"], "igb1")
	}
	if !sameValues(rec["tag"], "10") {
		t.Errorf("tag: stored %q, want %q", rec["tag"], "10")
	}
	if !sameValues(rec["pcp"], "0") {
		t.Errorf("pcp: stored %q, want %q", rec["pcp"], "0")
	}
	if !sameValues(rec["proto"], "") {
		t.Errorf("proto: stored %q, want %q", rec["proto"], "")
	}
	if !sameValues(rec["descr"], "IoT") {
		t.Errorf("descr: stored %q, want %q", rec["descr"], "IoT")
	}
	if got.Device.ValueString() == "" && rec["vlanif"] != "" {
		t.Error("computed device not read back")
	}

	plan.ID = got.ID
	plan.Device = got.Device
	plan.Tag = types.Int64Value(20)
	st = h.update(st, plan, &got)
	rec, _ = fake.Get("vlan", id)
	if !sameValues(rec["tag"], "20") {
		t.Errorf("tag: stored %q, want %q", rec["tag"], "20")
	}

	if _, ok := h.read(st, &got); !ok {
		t.Fatal("read removed the resource")
	}
	if imp, ok := h.importID(id); !ok || imp != id {
		t.Fatalf("import by uuid = %q", imp)
	}
	h.delete(st)
	if _, ok := fake.Get("vlan", id); ok {
		t.Fatal("still stored after delete")
	}
	if fake.Applies["interfaces/vlan_settings/reconfigure"] == 0 {
		t.Error("never applied")
	}
	bad := plan
	bad.PCP = types.StringValue("not-an-option")
	if !h.validateStrings(bad).HasError() {
		t.Error("invalid pcp accepted")
	}
}

